const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={autopilot:'Piloto automático',obstacles:'Esquivar obstáculos','road-feel':'Sensación de carretera',bike:'Bicicleta',character:'Personaje',difficulty:'Dificultad del rodillo',gearing:'Marchas virtuales'};
const metric=(value,unit)=>value==null?'—':Number(value).toLocaleString('es-CO',{maximumFractionDigits:1})+' '+unit;
export function courseDetails(course){return `<div class="course-head"><p class="eyebrow">RECORRIDOS DEL JUEGO <span data-game-count></span></p><h2 data-game-course-name>${safe(course?.name??'Cargando recorridos…')}</h2><p data-game-course-description>${safe(course?.description)}</p></div><div class="course-facts"><div><strong data-game-distance>${metric(course?.distanceKm,'km')}</strong><small>Distancia</small></div><div><strong data-game-ascent>${metric(course?.ascentM,'m')}</strong><small>Ascenso</small></div><div><strong data-game-category>${safe(course?.category||'—')}</strong><small>Categoría</small></div></div><p class="tiny" data-game-author>${safe(course?.author)}</p>`;}
export class GameControls {
 constructor(bridge){this.bridge=bridge;this.mode=null;this.pending=false;document.addEventListener('click',e=>this.click(e),true);document.addEventListener('change',e=>this.change(e),true);document.addEventListener('submit',e=>this.submit(e),true);document.querySelector('#modal').addEventListener('cancel',e=>{if(this.mode){e.preventDefault();this.run(()=>this.close());}});}
 get state(){return this.bridge.client.state;}
 get ui(){return this.state?.gameUi;}
 async run(work){if(this.pending)return;this.pending=true;this.update();try{await work();}catch(e){this.bridge.app.toast(e.message);}finally{this.pending=false;this.update();}}
 async send(action,params={}){return this.bridge.command(action,params);}
 afterRender(){if(!this.bridge.local)return;const heading=document.querySelector('.page-heading');if(heading&&!document.querySelector('#game-control-panel')&&['','#dashboard','#settings','#training'].includes(location.hash)){const section=document.createElement('section');section.className='card game-control-panel';section.id='game-control-panel';section.innerHTML=`<div class="card-header"><div><h2>Tu mando de GTBikeV</h2><span class="tiny" data-game-status>Esperando al juego</span></div><button class="btn ghost" data-action="game-open" data-menu="main">Menú en GTA V ↗</button></div><div class="game-shortcuts"><button data-action="game-open" data-menu="routes"><span>↝</span><strong>Recorridos</strong><small>Explorar y seleccionar</small></button><button data-action="game-open" data-menu="user"><span>◎</span><strong>Tu ciclista</strong><small>Peso, FTP y bicicleta</small></button><button data-action="game-open" data-menu="devices"><span>⌁</span><strong>Dispositivos</strong><small>Dificultad y sensores</small></button><button data-action="game-open" data-menu="workouts"><span>ϟ</span><strong>Entrenamientos</strong><small>Abrir en el juego</small></button></div><div class="game-toggle-row"><label><span>Piloto automático</span><input type="checkbox" data-game-toggle="autopilot"></label><label><span>Esquivar obstáculos</span><input type="checkbox" data-game-toggle="obstacles"></label></div><div class="game-active-course">Recorrido actual: <strong data-game-active-course>—</strong></div>`;heading.after(section);}this.update();}
 async open(menu){if(!this.bridge.local)return;await this.send('open-menu',{menu});if(['routes','user','devices','main'].includes(menu)){this.mode=menu;this.draw();}}
 draw(){const ui=this.ui??{},course=ui.course;let content='';if(this.mode==='routes'){content=`${courseDetails(course)}<label class="field">Ir a un recorrido<select id="game-course-list" aria-label="Recorrido del juego"></select></label><div class="course-arrows"><button class="btn" data-action="game-course-step" data-direction="-1">← Anterior</button><span data-game-position></span><button class="btn" data-action="game-course-step" data-direction="1">Siguiente →</button></div><div class="game-route-options"><label><input type="checkbox" data-game-course-option="loop"> Circular</label><label><input type="checkbox" data-game-course-option="reverse"> Invertir recorrido</label></div><button class="btn primary wide" data-action="game-course-select">Seleccionar este recorrido</button><p class="tiny" style="line-height:1.6">La selección cambia también en GTA V. El mapa y el perfil completo se muestran en la pantalla del juego.</p>`;}else if(this.mode==='main'){content='<p class="eyebrow">CONTROL DEL JUEGO</p><h2>Todo, a un toque.</h2><div class="game-menu-list">'+[['routes','Selección de recorrido'],['user','Ajustes de usuario'],['devices','Ajustes de dispositivos'],['workouts','Lista de workouts'],['sensors','Seleccionar sensores'],['multiplayer','Unirse a ruta multiplayer'],['about','Acerca de GTBikeV']].map(([id,title])=>`<button class="btn" data-action="game-open" data-menu="${id}">${title} <span>↗</span></button>`).join('')+'</div>';}else {const user=this.mode==='user';content=`<p class="eyebrow">AJUSTES EN EL JUEGO</p><h2>${user?'Tu ciclista, a tu medida.':'Tu rodillo. Tus reglas.'}</h2><p>Estos controles aplican el cambio a la sesión de GTBikeV.</p>${user?`<form id="game-profile-form"><div class="form-row"><label class="field">Peso (kg)<input name="weight" type="number" min="40" max="150" step="1" required value="${safe(ui.weightKg??75)}"></label><label class="field">FTP (W)<input name="ftp" type="number" min="50" max="500" step="1" required value="${safe(ui.ftpW??240)}"></label></div><button class="btn primary" type="submit">Aplicar peso y FTP</button></form>`:''}${(ui.options??[]).filter(o=>user?['bike','character'].includes(o.name):['difficulty','gearing'].includes(o.name)).map(o=>`<label class="field">${names[o.name]}<select data-game-option="${o.name}">${o.choices.map((label,i)=>`<option value="${i}" ${o.index===i?'selected':''}>${safe(label)}</option>`).join('')}</select></label>`).join('')}${user?'':`<label class="setting-row"><span>Sensación de carretera</span><input type="checkbox" data-game-toggle="road-feel"></label><button class="btn wide" data-action="game-open" data-menu="sensors">Seleccionar sensores en GTA V ↗</button>`}`;}
 this.bridge.app.modal(content+'<div class="game-dialog-footer"><button class="btn ghost" data-action="game-close">Cerrar en el juego</button><span class="tiny" data-game-feedback>Sincronizado con GTA V</span></div>');this.update();}
 update(){if(!this.bridge.local)return;const ui=this.ui,s=this.state,caps=s?.commands??[];const canOpen=caps.includes('open-menu');const panel=document.querySelector('#game-control-panel');if(panel){panel.querySelector('[data-game-status]').textContent=canOpen?'Control desde tu celular · Sincronizado con el mod':s?.modLoaded?'Actualiza el adaptador para habilitar los menús':'Conecta el adaptador del juego';panel.querySelector('[data-game-active-course]').textContent=ui?.activeCourse||'Sin recorrido seleccionado';}
 document.querySelectorAll('[data-action="game-open"]').forEach(el=>el.disabled=this.pending||!canOpen||el.dataset.menu==='routes'&&!ui?.routesEnabled||el.dataset.menu==='workouts'&&!ui?.workoutsEnabled);
 document.querySelectorAll('[data-game-toggle]').forEach(el=>{const setting=ui?.toggles?.find(x=>x.name===el.dataset.gameToggle);el.disabled=this.pending||!setting?.enabled||!caps.includes('game-toggle');if(document.activeElement!==el)el.checked=setting?.checked??false;});
 document.querySelectorAll('[data-game-option]').forEach(el=>{const setting=ui?.options?.find(x=>x.name===el.dataset.gameOption);el.disabled=this.pending||!setting?.enabled||!caps.includes('game-option');if(document.activeElement!==el&&setting)el.value=String(setting.index);});
 if(document.querySelector('#game-profile-form button'))document.querySelector('#game-profile-form button').disabled=this.pending||!caps.includes('game-profile');
 const feedback=document.querySelector('[data-game-feedback]');if(feedback)feedback.textContent=this.pending?'Aplicando en el juego…':!s?.adapterConnected?'Sin conexión con el juego':'Sincronizado con GTA V';
 if(this.mode==='routes'&&document.querySelector('#modal').open){const c=ui?.course;const set=(selector,value)=>{const el=document.querySelector(selector);if(el)el.textContent=value;};set('[data-game-course-name]',c?.name??'Esperando datos del juego');set('[data-game-course-description]',c?.description??'');set('[data-game-distance]',metric(c?.distanceKm,'km'));set('[data-game-ascent]',metric(c?.ascentM,'m'));set('[data-game-category]',c?.category||'—');set('[data-game-author]',c?.author?'Autor: '+c.author:'');set('[data-game-position]',c?`${c.index+1} / ${c.total}`:'—');const list=document.querySelector('#game-course-list');const signature=JSON.stringify(c?.choices??[]);if(list&&signature!==this.catalog){list.innerHTML=(c?.choices??[]).map(item=>`<option value="${item.index}">${safe(item.label)}</option>`).join('');this.catalog=signature;}if(list){list.disabled=this.pending||!c?.visible;if(document.activeElement!==list)list.value=String(c?.index??-1);}document.querySelectorAll('[data-game-course-option]').forEach(el=>{const k=el.dataset.gameCourseOption;el.disabled=this.pending||!c?.visible||!c[k+'Allowed'];if(document.activeElement!==el)el.checked=c?.[k]??false;});document.querySelectorAll('[data-action="game-course-step"],[data-action="game-course-select"]').forEach(el=>el.disabled=this.pending||!c?.visible||!c?.total);}
 }
 async close(){await this.send('close-menu');this.mode=null;this.catalog=null;document.querySelector('#modal').close();}
 click(e){const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='close'&&this.mode){e.preventDefault();e.stopImmediatePropagation();this.run(()=>this.close());return;}if(!this.bridge.local||!action?.startsWith('game-'))return;e.preventDefault();e.stopImmediatePropagation();this.run(async()=>{if(action==='game-open')await this.open(el.dataset.menu);if(action==='game-close')await this.close();if(action==='game-course-step')await this.send('browse-course',{direction:Number(el.dataset.direction),expectedKey:this.ui?.course?.key});if(action==='game-course-select')await this.send('select-course',{expectedKey:this.ui?.course?.key});});}
 change(e){if(!this.bridge.local)return;const el=e.target;if(el.dataset.gameToggle){this.run(()=>this.send('game-toggle',{name:el.dataset.gameToggle,enabled:el.checked}));}else if(el.dataset.gameOption){const setting=this.ui?.options.find(o=>o.name===el.dataset.gameOption);this.run(()=>this.send('game-option',{name:el.dataset.gameOption,index:Number(el.value),label:setting?.choices[Number(el.value)]}));}else if(el.dataset.gameCourseOption){this.run(()=>this.send('course-options',{[el.dataset.gameCourseOption]:el.checked,expectedKey:this.ui?.course?.key}));}else if(el.id==='game-course-list'){const item=this.ui?.course?.choices.find(x=>x.index===Number(el.value));this.run(()=>this.send('browse-course',{index:item?.index,key:item?.key,expectedKey:this.ui?.course?.key}));}}
 submit(e){if(e.target.id!=='game-profile-form')return;e.preventDefault();e.stopImmediatePropagation();const data=new FormData(e.target);this.run(()=>this.send('game-profile',{weight:Number(data.get('weight')),ftp:Number(data.get('ftp'))}));}
}
